package org.sleepwell.app;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import java.util.*;
/** Private audio consent and exact-ended-night queue; never part of portable record restoration. Worker-only. */
final class AutoCloudAudioStore extends SQLiteOpenHelper {
 static final String DATABASE="automatic_audio_backup_v1.db";
 AutoCloudAudioStore(Context app){super(app,DATABASE,null,1);}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE owner(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL,token TEXT NOT NULL,tree TEXT NOT NULL,revision INTEGER NOT NULL,since INTEGER NOT NULL,review TEXT NOT NULL,clips INTEGER NOT NULL,bytes INTEGER NOT NULL,message TEXT NOT NULL)");db.execSQL("INSERT INTO owner VALUES(1,0,'','',0,0,'',0,0,'Off · no automatic audio uploads')");db.execSQL("CREATE TABLE tasks(identity TEXT PRIMARY KEY,version TEXT NOT NULL,session INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,tree TEXT NOT NULL,revision INTEGER NOT NULL,token TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL,due INTEGER NOT NULL,uri TEXT NOT NULL DEFAULT '',sha TEXT NOT NULL DEFAULT '',size INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL DEFAULT '')");db.execSQL("CREATE INDEX audio_backup_due ON tasks(state,due)");}
 @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){throw new IllegalStateException("Unsupported automatic audio journal");}
 static final class Owner {final boolean enabled;final String token,tree,message;final long revision,since;Owner(Cursor row){enabled=row.getInt(0)!=0;token=row.getString(1);tree=row.getString(2);revision=row.getLong(3);since=row.getLong(4);message=row.getString(5);}}
 static final class Task {final String identity,version,tree,token,state;final long session,start,end,revision,due;final int attempts;Task(Cursor row){identity=row.getString(0);version=row.getString(1);session=row.getLong(2);start=row.getLong(3);end=row.getLong(4);tree=row.getString(5);revision=row.getLong(6);token=row.getString(7);state=row.getString(8);attempts=row.getInt(9);due=row.getLong(10);}}
 Owner owner(){try(Cursor row=getReadableDatabase().rawQuery("SELECT enabled,token,tree,revision,since,message FROM owner WHERE id=1",null)){if(!row.moveToFirst())throw new IllegalStateException("Audio consent is unavailable");return new Owner(row);}}
 void configure(boolean on,CloudBackupSettings.Destination destination,LibraryAudioArchive.Plan plan,String message){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.execSQL("UPDATE tasks SET state=CASE WHEN state='RUNNING' THEN 'UNCERTAIN' ELSE 'CANCELLED' END,message='Audio consent or destination changed; existing provider files stay untouched' WHERE state IN ('PENDING','RUNNING')");ContentValues values=new ContentValues();values.put("enabled",on?1:0);values.put("token",UUID.randomUUID().toString());values.put("tree",on?destination.tree:"");values.put("revision",on?destination.revision:0);values.put("since",on?System.currentTimeMillis():0);values.put("review",on?plan.metadata.fingerprint:"");values.put("clips",on?plan.audio.size():0);values.put("bytes",on?plan.bytes:0);values.put("message",message);db.update("owner",values,"id=1",null);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void message(String message){ContentValues values=new ContentValues();values.put("message",message);getWritableDatabase().update("owner",values,"id=1",null);}
 int count(String... states){StringJoiner in=new StringJoiner(",");for(String ignored:states)in.add("?");try(Cursor row=getReadableDatabase().rawQuery("SELECT count(*) FROM tasks WHERE state IN ("+in+")",states)){row.moveToFirst();return row.getInt(0);}}
 Task next(){try(Cursor row=getReadableDatabase().rawQuery("SELECT * FROM tasks WHERE state='PENDING' ORDER BY due,rowid LIMIT 1",null)){return row.moveToFirst()?new Task(row):null;}}
 void messageOwned(String token,String message){ContentValues values=new ContentValues();values.put("message",message);getWritableDatabase().update("owner",values,"id=1 AND enabled=1 AND token=?",new String[]{token});}
 void enqueue(long id,long start,long end){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{enqueueOwned(id,start,end);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 private void enqueueOwned(long id,long start,long end){Owner owner=owner();if(!owner.enabled||end<owner.since)return;String key=AutoCloudBackupPolicy.key(id,start,end,owner.revision,owner.tree);try(Cursor duplicate=getReadableDatabase().rawQuery("SELECT identity FROM tasks WHERE identity=?",new String[]{key})){if(duplicate.moveToFirst())return;}try(Cursor total=getReadableDatabase().rawQuery("SELECT count(*) FROM tasks",null)){total.moveToFirst();if(total.getInt(0)>=2048){message("Audio receipt journal is full. Use manual audio backup; no records were deleted.");return;}}if(count("PENDING","RUNNING")>=16){message("Audio backup queue is full. Save a manual audio version; queued nights are kept.");return;}ContentValues values=new ContentValues();values.put("identity",key);values.put("version",UUID.randomUUID().toString());values.put("session",id);values.put("start",start);values.put("end",end);values.put("tree",owner.tree);values.put("revision",owner.revision);values.put("token",owner.token);values.put("state","PENDING");values.put("attempts",0);values.put("due",System.currentTimeMillis()+60000);getWritableDatabase().insertOrThrow("tasks",null,values);message("Whole-library audio version queued after a successfully recorded night · waits for charging and unmetered network");}
 boolean claim(Task task){ContentValues values=new ContentValues();values.put("state","RUNNING");values.put("attempts",task.attempts+1);return getWritableDatabase().update("tasks",values,"identity=? AND token=? AND state='PENDING'",new String[]{task.identity,task.token})==1;}
 void finish(Task task,String status,String message,CloudAudioVersions.Entry receipt,long due){ContentValues values=new ContentValues();values.put("state",status);values.put("message",message);values.put("due",due);if(receipt!=null){values.put("uri",receipt.uri);values.put("sha",receipt.sha);values.put("size",receipt.zipBytes);}getWritableDatabase().update("tasks",values,"identity=? AND token=?",new String[]{task.identity,task.token});Owner owner=owner();if(owner.enabled&&owner.token.equals(task.token))messageOwned(task.token,message);}
 void expire(long now){ContentValues values=new ContentValues();values.put("state","CANCELLED");values.put("message","Audio request expired after seven days or its wall clock moved before the saved night. No provider file was created.");getWritableDatabase().update("tasks",values,"state='PENDING' AND (end<? OR end>?)",new String[]{Long.toString(now-7*86400000L),Long.toString(now)});}
 void recover(){getWritableDatabase().execSQL("UPDATE tasks SET state='UNCERTAIN',message='The process stopped during an audio save. A provider file may exist. No automatic replay.' WHERE state='RUNNING'");if(count("UNCERTAIN")>0)message("A previous audio save was interrupted or uncertain. Review Audio version history and the provider folder; it will not be retried automatically.");}
}
